const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const beijing = ee.Geometry.Point([116.4074, 39.9042]).buffer(50000); // 50km buffer around Beijing

  const janPeriod = ['2020-01-01', '2020-01-20'];
  const febPeriod = ['2020-02-10', '2020-02-25'];

  // 2. Data Acquisition
  const janCollection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .filterDate(janPeriod[0], janPeriod[1])
    .filterBounds(beijing)
    .select('NO2_column_number_density');

  const febCollection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .filterDate(febPeriod[0], febPeriod[1])
    .filterBounds(beijing)
    .select('NO2_column_number_density');

  // Check collection sizes
  const janSize = janCollection.size().getInfo();
  const febSize = febCollection.size().getInfo();

  console.log(`Jan Images: ${janSize}, Feb Images: ${febSize}`);

  if (janSize === 0 || febSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate mean composites
  const janMean = janCollection.mean();
  const febMean = febCollection.mean();

  // Get pixel counts and mean values
  const janStats = janMean.reduceRegion({
    reducer: ee.Reducer.mean().combine(ee.Reducer.count(), null, true),
    geometry: beijing,
    scale: 1000,
    maxPixels: 1e9
  });

  const febStats = febMean.reduceRegion({
    reducer: ee.Reducer.mean().combine(ee.Reducer.count(), null, true),
    geometry: beijing,
    scale: 1000,
    maxPixels: 1e9
  });

  const janMeanVal = janStats.get('NO2_column_number_density_mean').getInfo();
  const janCount = janStats.get('NO2_column_number_density_count').getInfo();
  const febMeanVal = febStats.get('NO2_column_number_density_mean').getInfo();
  const febCount = febStats.get('NO2_column_number_density_count').getInfo();

  console.log(`Jan NO2: ${janMeanVal?.toFixed(6)}, Pixels: ${janCount}`);
  console.log(`Feb NO2: ${febMeanVal?.toFixed(6)}, Pixels: ${febCount}`);

  // 4. Validation & Final Answer
  if (janCount === 0 || febCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  if (janMeanVal === null || febMeanVal === null || 
      isNaN(janMeanVal) || isNaN(febMeanVal) ||
      janMeanVal < 0 || febMeanVal < 0) { // NO2 should be positive
    console.log("<answer>C3</answer>");
    return;
  }

  // Check if February decreased compared to January
  const decreasePercent = ((janMeanVal - febMeanVal) / janMeanVal * 100);
  console.log(`Change: ${decreasePercent.toFixed(1)}%`);

  if (febMeanVal < janMeanVal) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
